/**
 * 安全响应头（P0-5）
 * ------------------------------------------------------------------
 * 关键点：**Cloudflare Pages 的 `_headers` 文件对 Pages Functions 的响应无效**
 * （官方明示：custom headers are not applied to responses generated by Pages Functions）。
 * 也就是说 /api/* 走的那套代码必须自己带上这些头，否则「配了 _headers 就以为全站都有」
 * 是假的——静态页有一半、API 一半没有，而真正处理口令和会话的恰恰是 API 那一半。
 *
 * 与静态侧 `_headers` 的 `/*` 块保持**同一套值**，避免两处漂移。
 * 改动这里请同步改 `tests/security-headers.test.mjs` 与 `_headers`。
 *
 * 说明（为什么 CSP 仍带 'unsafe-inline'）：
 * 全站 16 个被服务页面共 34 段内联 <script>（主题引导、配置初始化、每页 boot 等），
 * 均为静态、字节稳定、且无 eval/new Function。去掉 'unsafe-inline' 会让这些内联脚本
 * 全部被拦、整站功能损坏，因此本期 CSP 的价值定位是**堵住数据外传与嵌套**：
 * connect-src 'self'（XSS 也偷不走数据到第三方）、frame-ancestors 'none'（反点击劫持）、
 * object-src 'none'、base-uri/form-action 'self'。
 * 去 'unsafe-inline' 的可行路径是 **hash-based CSP**（对每段内联脚本计算 sha256 列入
 * script-src）；nonce 化在 CF Pages 静态托管下不可行（无逐请求 HTML 生成）。完整评估与
 * 迁移方案见 docs/CSP-hardening.md（P1-7）。style-src 的 'unsafe-inline' 因内联 style=
 * 属性仍存在，暂保留。
 *
 * P1-7b（hash-based 灰度，已落地）：内联脚本哈希表由 scripts/csp-hashes.mjs 从全部
 * HTML 实算生成（functions/api/_csp-hashes.js），script-src 以「'unsafe-inline' + 全部
 * hash」形式灰度——CSP3 浏览器见 hash 即忽略 'unsafe-inline'（只放行哈希命中块），
 * 旧浏览器回退 'unsafe-inline'。_headers 的 CSP 行由同一生成器写入，两边一致性由
 * tests/security-headers.test.mjs + tests/csp-hashes.test.mjs 双守卫钉死。
 * ⚠ 改任何 HTML 的内联脚本后必须重跑 node scripts/csp-hashes.mjs，否则现代浏览器
 * 会拦截未列入哈希的内联脚本（表现为页面功能静默失效）。
 */
import {cspWithInlineHashes} from "./_csp-hashes.js";
export const SECURITY_HEADERS={
 "x-content-type-options":"nosniff",
 "referrer-policy":"strict-origin-when-cross-origin",
 "x-frame-options":"DENY",
 "permissions-policy":"geolocation=(self), camera=(self), microphone=(), payment=(), usb=()",
 "content-security-policy":cspWithInlineHashes("default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; font-src 'self' data:; connect-src 'self'; media-src 'self' blob:; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'"),
 "strict-transport-security":"max-age=31536000"
};
/** 合并到已有 Headers 上（不覆盖业务自定义的头，如 set-cookie） */
export function withSecurityHeaders(headers){
 const h=new Headers(headers||undefined);
 for(const [k,v] of Object.entries(SECURITY_HEADERS))if(!h.has(k))h.set(k,v);
 return h;
}
const STATUS_CODE={400:"BAD_REQUEST",401:"UNAUTHORIZED",403:"FORBIDDEN",404:"NOT_FOUND",409:"CONFLICT",422:"UNPROCESSABLE_ENTITY",500:"INTERNAL_ERROR",503:"SERVICE_UNAVAILABLE",429:"TOO_MANY_REQUESTS"};
const MESSAGE_CODE={"请输入账号和密码":"AUTH_CREDENTIALS_REQUIRED","账号或密码错误":"AUTH_INVALID_CREDENTIALS","账号数据异常":"AUTH_USER_DATA_INVALID","账号已停用":"AUTH_USER_DISABLED","未登录":"AUTH_REQUIRED","无权限":"PERMISSION_DENIED","未选择线路":"ROUTE_NOT_SELECTED","线路不存在":"ROUTE_NOT_FOUND","请输入线路名称":"ROUTE_NAME_REQUIRED","线路已存在":"ROUTE_ALREADY_EXISTS","管理员不参与业务线路绑定":"ADMIN_BUSINESS_BINDING_FORBIDDEN","线路或岗位无效":"ROUTE_DUTY_INVALID","线路不存在或已停用":"ROUTE_INACTIVE","已有待审核申请":"ROUTE_REQUEST_PENDING","你已绑定其他线路":"ROUTE_ALREADY_BOUND","线路岗位已被占用":"ROUTE_DUTY_OCCUPIED","管理员不参与业务调度":"ADMIN_DISPATCH_FORBIDDEN","请选择调度线路":"DISPATCH_ROUTE_REQUIRED","无权维护该线路基准库":"BASE_MAINTENANCE_FORBIDDEN","无权维护该线路数据资料":"BASE_MAINTENANCE_FORBIDDEN","缺少确认请求ID":"CONFIRM_REQUEST_ID_REQUIRED","确认请求正在处理中，请稍后再试":"CONFIRM_REQUEST_BUSY","stores 必须是数组":"BASE_STORES_INVALID","门店ID重复":"BASE_STORE_ID_DUPLICATE","运单信息不完整":"WAYBILL_INFO_INCOMPLETE","运单提交格式错误":"WAYBILL_FORM_INVALID","请选择运单":"WAYBILL_FILE_REQUIRED","请先选择调度线路":"DISPATCH_ROUTE_REQUIRED","无权处理运单":"WAYBILL_PROCESS_FORBIDDEN","今日运单数据异常":"WAYBILL_DATA_INVALID","注册失败，请稍后重试":"REGISTER_FAILED","注册服务异常，请稍后重试":"REGISTER_INTERNAL_ERROR"};
function codeFor(data,status){if(data?.code)return data.code;if(!data?.error)return null;return MESSAGE_CODE[data.error]||("HTTP_"+status+"_"+(STATUS_CODE[status]||"ERROR"))}
// extraHeaders：给限流的 Retry-After 这类「按响应而变」的头留口子，
// 业务自定义的头不会被安全头覆盖（withSecurityHeaders 只在缺失时写入）。
export function json(data,status=200,extraHeaders){const payload={...data};const code=codeFor(payload,status);if(code)payload.code=code;const headers=new Headers({"content-type":"application/json; charset=utf-8","cache-control":"no-store"});if(extraHeaders)for(const [k,v] of Object.entries(extraHeaders))headers.set(k,v);return new Response(JSON.stringify(payload),{status,headers:withSecurityHeaders(headers)})}
export async function body(request){try{return await request.json()}catch{return {}}}
